# A paid model at 0.00 in these statuses has no price yet: its package starts unpriced.
UNPRICED_STATUSES = ("draft", "pending_review", "awaiting_price", "rejected")


def give_packages_a_kind(apps, schema_editor):
    """Each product's zip becomes its Whole File package, with the product's price.

    Old imports have one zip (<ID>.zip or package.zip). When a product has several files that
    are not the preview (admin uploads), the newest .zip (else the newest file) becomes Whole
    File, and the others keep a blank kind. The product's price fields already equal the
    package's, so the summary price (products.packages.sync_summary_price) needs no update.
    """
    Product = apps.get_model("products", "Product")
    ProductFile = apps.get_model("products", "ProductFile")
    for product in Product.objects.filter(files__is_preview=False).distinct().iterator():
        files = list(
            ProductFile.objects.filter(product=product, is_preview=False).order_by(
                "-created_at", "-pk"
            )
        )
        zips = [row for row in files if row.storage_path.lower().endswith(".zip")]
        package = (zips or files)[0]
        unpriced = (
            product.price == 0
            and product.status in UNPRICED_STATUSES
            and not is_free_model_path(package.storage_path)
        )
        package.package_kind = "whole"
        if not unpriced:
            package.price = product.price
            package.discount_price = product.discount_price
            package.discount_ends_at = product.discount_ends_at
        package.save(
            update_fields=["package_kind", "price", "discount_price", "discount_ends_at"]
        )


